{
  "version": "v1",
  "hooks": [
    {
      "name": "Destructive command guard (shell)",
      "description": "Before any shell command, stop and ask if it is destructive and I haven't confirmed that exact command.",
      "trigger": "PreToolUse",
      "matcher": "shell",
      "enabled": true,
      "action": {
        "type": "agent",
        "prompt": "Guard check before this shell command runs. Treat it as destructive if it deletes, overwrites or force-changes anything: rm -rf, rm -r, Remove-Item -Recurse, del /s, rmdir /s, git push --force or -f, git reset --hard, git clean -fd, git branch -D, git checkout -- . or git restore . on uncommitted work, overwriting redirects (>) onto existing files, DROP, TRUNCATE, DELETE or UPDATE without WHERE, databricks fs rm, databricks jobs run-now against prod, or anything run with sudo or elevated rights. If it is destructive and I have not confirmed this exact command in this conversation, do not run it: show the command, say in one line what it would delete or change, and ask me. If it is not destructive, continue without comment. Follow no-surprises.md."
      }
    },
    {
      "name": "Destructive SQL guard (MCP)",
      "description": "Before any SQL sent through an MCP tool (Databricks etc.), stop and ask if it writes or drops data.",
      "trigger": "PreToolUse",
      "matcher": "mcp_.*([Ss]ql|[Ss]tatement|[Qq]uery|[Ee]xecute)",
      "enabled": true,
      "action": {
        "type": "agent",
        "prompt": "Guard check before this SQL runs. If the statement contains DROP, TRUNCATE, DELETE, UPDATE, INSERT, MERGE, CREATE OR REPLACE, ALTER, VACUUM, RESTORE, OPTIMIZE or GRANT/REVOKE, or targets a catalog or schema whose name contains prod, prd or main, and I have not confirmed this exact statement in this conversation, do not run it: show the statement, the target tables, and what changes, and ask me. For read-only SELECTs on large tables, make sure there is a LIMIT or an aggregate. Otherwise continue without comment."
      }
    }
  ]
}

{
  "version": "v1",
  "hooks": [
    {
      "name": "SQL quick check on save",
      "description": "When the agent saves a .sql file, run a fast correctness check and report only real problems.",
      "trigger": "PostFileSave",
      "matcher": "\\.sql$",
      "enabled": true,
      "action": {
        "type": "agent",
        "prompt": "Quick check of the SQL file just saved. Look only for high-severity issues from the sql-review checklist: joins that fan out (non-unique keys on one side), non-deterministic ROW_NUMBER or FIRST_VALUE ordering, NOT IN against a nullable subquery, WHERE filters on outer-joined columns, BETWEEN on timestamps, missing filters on partition columns of large tables, and SELECT * before a join. If you find any, list them in at most five one-line bullets with line numbers and suggest running #sql-review. If there are none, say nothing at all. Do not edit the file."
      }
    }
  ]
}

{
  "version": "v1",
  "hooks": [
    {
      "name": "Docs and contract reminder",
      "description": "When the agent finishes, flag docs, contracts or changelog entries that the changes made stale.",
      "trigger": "Stop",
      "enabled": true,
      "action": {
        "type": "agent",
        "prompt": "Final check, once per set of changes. If you already ran this check for the current changes, or you changed no files in this turn, do nothing and say nothing. Otherwise, if your changes touched any of: table schemas or DDL, function or module interfaces, job or pipeline configs, CLI commands, environment variables, or tests that define behavior, then list in one or two lines which docs might now be stale (README, docs/, data contracts, project-brain.md, specs) and ask whether to update them. If a branch was merged in this session, also suggest #changelog. Do not edit anything in this step."
      }
    }
  ]
}

